import{_ as a,C as l,o as n,c as r,E as t,a3 as o}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"千字文","description":"南朝梁周兴嗣编次的蒙学韵文，一千个不重复的字，四字一句、两句一韵。","frontmatter":{"title":"千字文","description":"南朝梁周兴嗣编次的蒙学韵文，一千个不重复的字，四字一句、两句一韵。","category":"guide","aliases":["千字文","千字文全篇","qianziwen"],"source":["《千字文》（通行本）"]},"headers":[],"relativePath":"lizhimingde/qianziwen/index.md","filePath":"lizhimingde/qianziwen/index.md","lastUpdated":1789470132000}'),h={name:"lizhimingde/qianziwen/index.md"};function d(c,i,s,m,p,z){const e=l("BookCover");return n(),r("div",null,[t(e,{title:"千字文",subtitle:"南朝梁 · 周兴嗣 编次",summary:"相传梁武帝从王羲之书法中拓出一千个不重复的字，命周兴嗣编成韵文；全文四字一句、两句一韵，一千字不重不漏。它本是童蒙识字课本，却由识字铺开成一篇缩写的中国文化小百科——从天地开辟讲到日用起居，中间夹着上古史、修身、人伦、都邑、史地与农政。"}),i[0]||(i[0]=o('<h2 id="篇目" tabindex="-1">篇目 <a class="header-anchor" href="#篇目" aria-label="Permalink to &quot;篇目&quot;">​</a></h2><p>全书只有一篇，一页读完；页内按内容分为八节：</p><ul><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-1">一、天地自然</a> —— 天地初分、日月寒暑，以及金玉、果蔬、鱼鸟</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-2">二、上古治世</a> —— 官制与文字衣裳、禅让与汤武、德化所及</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-3">三、修身之本</a> —— 身体发肤、五常、改过、言行与惜时</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-4">四、人伦持守</a> —— 事亲事君、孝忠谨敬、亲族与交游，收到守真</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-5">五、都邑典籍</a> —— 两京形势、宫殿朝会，以及坟典与群英</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-6">六、史地农政</a> —— 贤相霸主名将、律法兴衰、九州山川与稼穑</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-7">七、为政隐逸</a> —— 在朝的操守戒备，与退居后的读书看山</li><li><a href="/Dao/lizhimingde/qianziwen/chapter-01#jie-8">八、起居收束</a> —— 日用起居、诸般技艺、天时祝愿，与语助收尾</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先顺着<a href="/Dao/lizhimingde/qianziwen/chapter-01">全篇原文</a>把八节通读一遍，遇到不认得的字不必停下；竹简 / 经典两种读法可随时切换</li><li>再看每节的「逐句释义」——逐句有译文，句下的字词注解释难字与典故</li><li>「字词」卡片是重点词的速查——生僻字在经典模式下点词可看释义，典故与关键词列在卡片里</li><li>最后读「现代解读与启发」——那是读完全篇后的一点收束，也欢迎你写下自己的</li></ol><p>全篇末尾还有三个附录：<a href="/Dao/lizhimingde/qianziwen/chapter-01#附录一重要典故速查">重要典故速查</a>、<a href="/Dao/lizhimingde/qianziwen/chapter-01#附录二难读字注音">难读字注音</a>、<a href="/Dao/lizhimingde/qianziwen/chapter-01#附录三背景简介">背景简介</a>。</p><h2 id="关于这个站" tabindex="-1">关于这个站 <a class="header-anchor" href="#关于这个站" aria-label="Permalink to &quot;关于这个站&quot;">​</a></h2><ul><li>底本：通行本《千字文》，文字以本次录入的文本为准（个别字通行本或作异文，如「闰余成岁」一作「闰馀成岁」、「纨扇圆絜」一作「纨扇圆洁」，此处一仍录入本）</li><li>「一千字不重不漏」在繁体系统下成立；简体因合并字（云／雲、发／髮、并／並、戚／慼、昆／崑）会有五字两见</li><li>《千字文》属公共领域；本站只做原文录入、分段与字词释义，不搬录现代译注</li><li>页面结构：导读 → 原文 → 引读 → 逐句释义 → 字词 → 现代解读与启发（八节同例），末尾附典故速查表、难读字注音表与背景简介</li><li>工程与换书方式见 <code>README.md</code></li></ul>',8))])}const q=a(h,[["render",d]]);export{_ as __pageData,q as default};
